var APGAR_CRIT=['皮肤颜色','心率','反射刺激反应','肌张力','呼吸'];
function apgar(a,p,g,ac,r){ a=+a;p=+p;g=+g;ac=+ac;r=+r;
  if([a,p,g,ac,r].some(function(x){return isNaN(x)||x<0||x>2;})) return {error:'每项须为 0–2 的整数'};
  var sum=a+p+g+ac+r, level, tip;
  if(sum>=7){ level='正常'; tip='评分 7–10：新生儿状况良好，通常无需特殊处理。'; }
  else if(sum>=4){ level='轻度抑制'; tip='评分 4–6：需保暖、清理气道、给氧等初步处理。'; }
  else { level='重度抑制'; tip='评分 0–3：需立即复苏（通气、胸外按压、用药）。'; }
  return {sum:sum, level:level, tip:tip};
}
var EXPORTS={apgar:apgar, criteria:APGAR_CRIT};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ApgarForgePure = EXPORTS; }
